const keysANDBy = {
    CurrentTicket: "currentTicketID",
	Car: "carID",
	CommonMake: "makeID",
	CommonModel: "modeID",
	Customer: "customerID",
	TicketSequence: "currentTicketID",
	Transaction: "transactionID",
	TicketType: "ticketTypeID",
	ParkLocation: "parkLocationID",
	ParkArea: "parkAreaID",
	CompanyArrival:	"companyArrivalID",
	EventParty:	"eventPartyID",
	Color: "colorID",
	CurrentUser: "userID",
	PropertyUser: "userID",
	RecentActivityType:	"recentActivityTypeID",
	RecentActivity:	"recentActivityID",
	Chat: "chatID"
};

forEach(keysANDBy, (itemID: any, key: any) => {
    initializeMap[key as any] = keyBy(rawInitializeData[key as any] as any, itemID) as any;
});

